					return
				}
			}
		}()
	}
	for reader := 0; reader < 2; reader++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for round := 0; round < 40; round++ {
				page, err := target.QueryTxs(TxQuery{})
